package android.widget;
public class Toolbar extends LinearLayout { public Toolbar(android.content.Context c) { super(c); } public Toolbar(android.content.Context c,android.util.AttributeSet a) { super(c,a); } public Toolbar(android.content.Context c,android.util.AttributeSet a,int s) { super(c,a,s); } public Toolbar(android.content.Context c,android.util.AttributeSet a,int s,int r) { super(c,a,s,r); }  private TextView title,subtitle; private android.graphics.drawable.Drawable navigation; public void setTitle(CharSequence t) { if(title==null) { title=new TextView(getContext()); addView(title); } title.setText(t); } public void setTitle(int id) { setTitle(getContext().getText(id)); } public CharSequence getTitle() { return title==null?null:title.getText(); } public void setSubtitle(CharSequence t) { if(subtitle==null) { subtitle=new TextView(getContext()); addView(subtitle); } subtitle.setText(t); } public CharSequence getSubtitle() { return subtitle==null?null:subtitle.getText(); } public void setNavigationIcon(android.graphics.drawable.Drawable d) { navigation=d; } public android.graphics.drawable.Drawable getNavigationIcon() { return navigation; } public void setNavigationOnClickListener(android.view.View.OnClickListener l) {} }
